var browserConnectCmd = &cobra.Command{
	Use:   "connect",
	Short: "Connect to the browser DVE websocket",
	Long: `Connect to the browser DVE websocket, register the node identity,
and stream task/heartbeat messages until interrupted.

Example:
  knirv dve browser connect --wallet gno1abc123... --auth-token <jwt> --server http://localhost:8084`,
	RunE: func(cmd *cobra.Command, args []string) error {
		server, _ := cmd.Flags().GetString("server")
		authToken, _ := cmd.Flags().GetString("auth-token")
		wallet, _ := cmd.Flags().GetString("wallet")
		extensionID, _ := cmd.Flags().GetString("extension-id")
		capStr, _ := cmd.Flags().GetString("capabilities")
		badgeStr, _ := cmd.Flags().GetString("badge-nft-ids")
		browserVersion, _ := cmd.Flags().GetString("browser-version")
		heartbeatInterval, _ := cmd.Flags().GetDuration("heartbeat-interval")

		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		defer cancel()

		resolvedWallet, err := resolveWalletAddress(ctx, wallet)
		if err != nil {
			return err
		}

		identity := core.DeriveBrowserDVEIdentity(resolvedWallet, extensionID, browserVersion)
		capabilities := splitCSVFlag(capStr)
		badgeNFTIDs := splitCSVFlag(badgeStr)

		clientLogger := logrus.New()
		clientLogger.SetLevel(logrus.InfoLevel)

		client := core.NewBrowserDVEClient(
			server,
			authToken,
			identity,
			core.WithBrowserDVELogger(clientLogger),
			core.WithBrowserDVECapabilities(capabilities),
			core.WithBrowserDVEBadgeNFTIDs(badgeNFTIDs),
			core.WithBrowserDVEHeartbeatInterval(heartbeatInterval),
		)

		client.On("task_assigned", func(message core.BrowserDVEMessage) {
			fmt.Printf("[task_assigned] %s\n", string(message.Payload))
		})
		client.On("policy_sync", func(message core.BrowserDVEMessage) {
			fmt.Printf("[policy_sync] %s\n", string(message.Payload))
		})
		client.On("badge_refresh", func(message core.BrowserDVEMessage) {
			fmt.Printf("[badge_refresh] %s\n", string(message.Payload))
		})
		client.On("heartbeat_ack", func(message core.BrowserDVEMessage) {
			fmt.Printf("[heartbeat_ack] %s\n", string(message.Payload))
		})
		client.On("ws_register", func(message core.BrowserDVEMessage) {
			fmt.Printf("[ws_register] %s\n", string(message.Payload))
		})
		client.On("*", func(message core.BrowserDVEMessage) {
			if message.Type == "task_assigned" || message.Type == "policy_sync" || message.Type == "badge_refresh" || message.Type == "heartbeat_ack" || message.Type == "ws_register" {
				return
			}
			fmt.Printf("[%s] %s\n", message.Type, string(message.Payload))
		})

		ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
		defer stop()

		if err := client.Connect(ctx); err != nil {
			return fmt.Errorf("failed to connect browser DVE websocket: %w", err)
		}

		fmt.Printf(
			"Connected browser DVE node %s (%s) at %s\n",
			identity.NodeID,
			identity.DVEURI,
			server,
		)
		fmt.Println("Press Ctrl+C to disconnect.")

		<-ctx.Done()

		if err := client.Disconnect(); err != nil {
			return fmt.Errorf("failed to disconnect browser DVE websocket: %w", err)
		}

		fmt.Println("Disconnected browser DVE websocket.")
		return nil
	},
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func splitCSVFlag(value string) []string {
	parts := strings.Split(value, ",")
	result := make([]string, 0, len(parts))
	for _, part := range parts {
		trimmed := strings.TrimSpace(part)
		if trimmed != "" {
			result = append(result, trimmed)
		}
	}
	return result
}

package cmd

import (
	"fmt"
	"os"

	"github.com/sirupsen/logrus"
	"github.com/spf13/cobra"
	"github.com/spf13/viper"
)

var (
	cfgFile      string
	nodeURL      string
	verbose      bool
	logLevel     string
	logFormat    string
	aiProvider   string
	aiModel      string
	enableTUI    bool
	theme        string
	colorMode    string
	noAnimations bool

	log = logrus.New()

	rootCmd = &cobra.Command{
		Use:   "knirv",
		Short: "KNIRV Network CLI tool for blockchain and model operations",
		Long: `KNIRV Network CLI is a comprehensive command-line interface for interacting with the KNIRV ecosystem.
It enables developers to manage wallets, register capabilities, forge models, and interact with the blockchain ecosystem.`,
		PersistentPreRun: func(cmd *cobra.Command, args []string) {
			// Set up logging based on flags
			if verbose {
				log.SetLevel(logrus.DebugLevel)
			} else {
				switch logLevel {
				case "debug":
					log.SetLevel(logrus.DebugLevel)
				case "info":
					log.SetLevel(logrus.InfoLevel)
				case "warn":
					log.SetLevel(logrus.WarnLevel)
				case "error":
					log.SetLevel(logrus.ErrorLevel)
				default:
					log.SetLevel(logrus.InfoLevel)
				}
			}

			// Set log format
			if logFormat == "json" {
				log.SetFormatter(&logrus.JSONFormatter{})
			} else {
				log.SetFormatter(&logrus.TextFormatter{
					FullTimestamp: true,
				})
			}
		},
	}
)

// Execute adds all child commands to the root command and sets flags appropriately.
// This is called by main.main(). It only needs to happen once to the rootCmd.
func Execute() {
	if err := rootCmd.Execute(); err != nil {
		fmt.Println(err)
		os.Exit(1)
	}
}

// GetRootCmd returns the root command for use in REPL mode
func GetRootCmd() *cobra.Command {
	return rootCmd
}

func init() {
	cobra.OnInitialize(initConfig)

	// Add WASM command
	rootCmd.AddCommand(wasmCmd)
	// Add oracled command
	rootCmd.AddCommand(oracledCmd)

	// Global flags
	rootCmd.PersistentFlags().StringVar(&cfgFile, "config", "", "config file (default is $HOME/.knirv.yaml)")
	rootCmd.PersistentFlags().StringVar(&nodeURL, "node-url", "", "URL of the KNIRVCHAIN node")
	rootCmd.PersistentFlags().BoolVar(&verbose, "verbose", false, "enable verbose logging")
	rootCmd.PersistentFlags().StringVar(&logLevel, "log-level", "info", "set logging level (debug, info, warn, error)")
	rootCmd.PersistentFlags().StringVar(&logFormat, "log-format", "text", "set logging format (text, json)")
	rootCmd.PersistentFlags().StringVar(&aiProvider, "ai-provider", "openai", "AI provider to use (openai, anthropic)")
	rootCmd.PersistentFlags().StringVar(&aiModel, "ai-model", "", "AI model to use for generation")
	rootCmd.PersistentFlags().BoolVar(&enableTUI, "tui", false, "enable terminal UI mode with bubbletea")
	rootCmd.PersistentFlags().StringVar(&theme, "theme", "default", "set UI theme (default, dark, light, high-contrast)")
	rootCmd.PersistentFlags().StringVar(&colorMode, "color-mode", "256", "set color mode (16, 256, truecolor)")
	rootCmd.PersistentFlags().BoolVar(&noAnimations, "no-animations", false, "disable UI animations")

	// Bind flags to viper
	viper.BindPFlag("node_url", rootCmd.PersistentFlags().Lookup("node-url"))
	viper.BindPFlag("log_level", rootCmd.PersistentFlags().Lookup("log-level"))
	viper.BindPFlag("log_format", rootCmd.PersistentFlags().Lookup("log-format"))
	viper.BindPFlag("ai.provider", rootCmd.PersistentFlags().Lookup("ai-provider"))
	viper.BindPFlag("ai.default_model", rootCmd.PersistentFlags().Lookup("ai-model"))
	viper.BindPFlag("ui.enable_tui", rootCmd.PersistentFlags().Lookup("tui"))
	viper.BindPFlag("ui.theme", rootCmd.PersistentFlags().Lookup("theme"))
	viper.BindPFlag("ui.color_mode", rootCmd.PersistentFlags().Lookup("color-mode"))
	viper.BindPFlag("ui.animation_speed", rootCmd.PersistentFlags().Lookup("no-animations"))
}

// initConfig reads in config file and ENV variables if set.
func initConfig() {
	if cfgFile != "" {
		// Use config file from the flag.
		viper.SetConfigFile(cfgFile)
	} else {
		// Find home directory.
		home, err := os.UserHomeDir()
		if err != nil {
			// Log the error but don't exit; Viper might still find the config
			// through other means (e.g., --config flag, env vars), or the config
			// might not be strictly required for all commands or test scenarios.
			log.Warnf("Error finding home directory: %v. Will not search for config in home directory.", err)
		} else {
			// Search config in home directory with name ".knirv" (without extension).
			viper.AddConfigPath(home)
			viper.SetConfigName(".knirv")
		}
	}

	viper.AutomaticEnv() // read in environment variables that match

	// If a config file is found, read it in.
	if err := viper.ReadInConfig(); err == nil {
		log.Debugf("Using config file: %s", viper.ConfigFileUsed())
	}
}

